export type ScheduleEntry = { id: number; lab: string; bookedBy: string };

// Returns the entry with this id.
export function findEntry(schedule: ScheduleEntry[], id: number): ScheduleEntry {
  return schedule.find((e) => e.id === id) as ScheduleEntry;
}

// Who booked entry "id"? "(unknown)" when there is no such entry.
export function bookerOf(schedule: ScheduleEntry[], id: number): string {
  return findEntry(schedule, id).bookedBy;
}

