// capacity: null = not recorded yet (use the default), 0 = closed for maintenance.
export type Lab = { code: string; capacity: number | null };
export const DEFAULT_CAPACITY = 40;

export function capacityOf(lab: Lab): number {
  return lab.capacity || DEFAULT_CAPACITY;
}

// note: null = no note. An empty string is a real (empty) note and must stay empty.
export function noteOf(note: string | null): string {
  return note || '(no note)';
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { capacityOf, noteOf } from '../src/lab.ts';

test('a lab with no recorded capacity gets the default 40', () => assert.equal(capacityOf({ code: 'BE-202', capacity: null }), 40));
test('a lab closed for maintenance has 0 seats', () => assert.equal(capacityOf({ code: 'AL-301', capacity: 0 }), 0));
test('a normal lab keeps its capacity', () => assert.equal(capacityOf({ code: 'BE-201', capacity: 35 }), 35));
test('no note shows (no note)', () => assert.equal(noteOf(null), '(no note)'));
test('an empty note stays empty', () => assert.equal(noteOf(''), ''));

