export type Entry = { id: bigint; lab: string };

// Booking ids come from a PostgreSQL bigint column and can be larger than 2^53.
export function parseId(text: string): bigint {
  return BigInt(text);
}

// The JSON the API sends. The id must keep every digit (send it as a string).
export function toJson(e: Entry): string {
  return JSON.stringify(e);
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { parseId, toJson } from '../src/id.ts';

test('a big id keeps every digit in JSON', () =>
  assert.equal(toJson({ id: 9007199254740993n, lab: 'BE-201' }), '{"id":"9007199254740993","lab":"BE-201"}'));
test('parseId gives a bigint you can do bigint maths with', () => assert.equal(parseId('9007199254740993') + 1n, 9007199254740994n));

import { parseId } from '../src/id.ts';

const asNumber: number = parseId('7'); // expect TS2322
parseId('7') + 1; // expect TS2365

